    @BoundedFormula.Realize _ A (@sumStructure M _ A _ ((B.extend n).structure ρ)) _ _
        (extendRel w φ) u xs ↔
      @BoundedFormula.Realize _ A (@sumStructure M _ A _ (B.structure (atTuple ρ (u ∘ w)))) _ _
        φ u xs

