theorem moveTo_keepMid {q : Ph T Dm} {pts : Fin n → X.Map A}
    {σs : Fin n → X.pointBlock.Assignment A}
    (hkeep : ∀ e ∈ keepOff n (isMid d n), pointAssign (pts e.1) = σs e.2)
