theorem ParamTCSpec.reachAt_of_equiv (s : ParamTCSpec L'') (z : Fin s.par → M) (a b : s.Node M) :
    @ParamTCSpec.ReachAt L'' s N instN (e ∘ z) (a.1, e ∘ a.2) (b.1, e ∘ b.2) ↔
      @ParamTCSpec.ReachAt L'' s M instM z a b

theorem inflLimit_toStepDef : ∀ {L : Language.{0, 0}} (T : TCTower L) (A : Type)
    [instA : L.Structure A] [Finite A],
    @StepDef.inflLimit L T.toStepDef A instA = @reachAssign L T A instA

